<script setup lang="ts">
import {computed, onMounted, ref} from 'vue';
import {ArrowRight, ArrowUpRight, CalendarDays, CircleCheck, Clock3, Eye, Leaf, MessageCircle, PanelTop, RefreshCw, Settings2, ShieldCheck, Users} from 'lucide-vue-next';
import type {AdminContentResponse, DashboardStats} from '@yp666/shared';
import {api} from '../api';
import {dateTime} from '../utils';
const emit = defineEmits<{(e: 'navigate', section: string): void}>();
const stats = ref<DashboardStats>();
const content = ref<AdminContentResponse>();
const loading = ref(false);
const error = ref('');
const today = new Intl.DateTimeFormat('zh-CN', {month: 'long', day: 'numeric', weekday: 'long'}).format(new Date());
const max = computed(() => Math.max(1, ...(stats.value?.recentVisits.map(v => v.visits) || [1])));
function points(key: 'visits' | 'verified') {const rows = stats.value?.recentVisits || []; return rows.map((r, i) => `${rows.length === 1 ? 300 : 45 + i * (570 / (rows.length - 1))},${185 - r[key] / max.value * 145}`).join(' ');}
async function load() {loading.value = true; error.value = ''; try {const result = await Promise.all([api<DashboardStats>('/admin/dashboard'), api<AdminContentResponse>('/admin/content')]); stats.value = result[0]; content.value = result[1];} catch (e) {error.value = (e as Error).message;} finally {loading.value = false;}}
onMounted(load);
</script>
<template>
  <section class="dashboard-page" v-loading="loading">
    <div class="page-heading"><div><div class="eyebrow">YOUR WORKSPACE, AT A GLANCE</div><h1>照顾好每一次相遇<span class="heading-dot">.</span></h1><p>从这里，了解会客厅的近况。</p></div><div class="date-pill"><CalendarDays :size="16"/>{{today}}</div></div>
    <div v-if="error" class="error-panel"><p>{{error}}</p><el-button @click="load">重新加载</el-button></div>
    <template v-else>
      <div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>今日访问</span><span class="stat-icon"><Eye :size="18"/></span></div><strong>{{stats?.visitsToday ?? '—'}}<small>人次</small></strong><p>今天来到会客厅的访客</p></article><article class="stat-card"><div class="stat-top"><span>完成验证</span><span class="stat-icon"><ShieldCheck :size="18"/></span></div><strong>{{stats?.verifiedToday ?? '—'}}<small>人次</small></strong><p>已通过安全验证的访客</p></article><article class="stat-card"><div class="stat-top"><span>累计咨询</span><span class="stat-icon"><MessageCircle :size="18"/></span></div><strong>{{stats?.totalConversations ?? '—'}}<small>个会话</small></strong><p>每个问题，都值得认真回应</p></article><article class="stat-card stat-unread"><div class="stat-top"><span>待查看咨询</span><span class="stat-icon"><Clock3 :size="18"/></span></div><strong>{{stats?.unreadConversations ?? '—'}}<small>个会话</small></strong><button @click="emit('navigate', 'messages')">前往处理<ArrowRight :size="14"/></button></article></div>
      <div class="dashboard-middle"><article class="panel trend-panel"><div class="panel-heading"><div><h2>访客足迹</h2><p>最近 7 天的访问与验证记录</p></div><button class="icon-btn" aria-label="刷新统计" @click="load"><RefreshCw :size="16"/></button></div><div class="chart-legend"><span><i class="legend-visits"></i>访问人数</span><span><i class="legend-verified"></i>完成验证</span></div><div v-if="stats?.recentVisits.length" class="trend-chart"><svg viewBox="0 0 650 220" role="img" aria-label="最近七天访问人数和完成验证人数趋势"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#7b9e85" stop-opacity=".19"/><stop offset="100%" stop-color="#7b9e85" stop-opacity="0"/></linearGradient></defs><line v-for="i in 4" :key="i" x1="40" x2="625" :y1="40 + (i - 1) * 48" :y2="40 + (i - 1) * 48" stroke="#eaece5" stroke-dasharray="4 5"/><polygon :points="`45,185 ${points('visits')} 615,185`" fill="url(#chart-fill)"/><polyline :points="points('visits')" fill="none" stroke="#547861" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><polyline :points="points('verified')" fill="none" stroke="#b4bc99" stroke-width="2" stroke-dasharray="5 5"/><text v-for="(row, i) in stats.recentVisits" :key="row.date" :x="stats.recentVisits.length === 1 ? 300 : 45 + i * (570 / (stats.recentVisits.length - 1))" y="213" text-anchor="middle" fill="#92998d" font-size="11">{{row.date.slice(5)}}</text><text x="22" y="45" fill="#92998d" font-size="10">{{max}}</text><text x="22" y="189" fill="#92998d" font-size="10">0</text></svg></div><div v-else class="empty-small"><Leaf :size="30"/><p>第一位访客的足迹，即将从这里开始。</p></div></article>
      <article class="panel publish-panel"><div class="panel-heading"><div><h2>会客厅状态</h2><p>当前对外展示的版本</p></div><span class="soft-badge"><CircleCheck :size="12"/>已发布</span></div><div class="site-status-art"><Leaf :size="46" :stroke-width="1"/><span>{{content?.published.settings.brandName || '青屿'}}</span><small>每一次连接，都值得用心</small></div><div class="status-row"><span>最近发布</span><strong>{{dateTime(content?.publishedAt)}}</strong></div><div class="status-row"><span>访客验证</span><strong>{{content?.published.settings.verificationEnabled ? '已开启' : '未开启'}}</strong></div><div class="status-row"><span>展示内容</span><strong>{{content?.published.blocks.filter(v => v.enabled).length ?? 0}} 个内容模块</strong></div><el-button class="full-width" @click="emit('navigate', 'content')">管理页面内容<ArrowRight :size="14"/></el-button></article></div>
      <div class="section-label"><h2>让会客厅更好一点</h2><span>常用操作</span></div><div class="quick-actions"><button @click="emit('navigate', 'content')"><span class="quick-icon"><PanelTop :size="21"/></span><div><strong>更新内容</strong><p>编辑图文，让访客了解更多</p></div><ArrowUpRight :size="18"/></button><button @click="emit('navigate', 'settings')"><span class="quick-icon"><Settings2 :size="21"/></span><div><strong>布置会客厅</strong><p>调整名称、背景与欢迎语</p></div><ArrowUpRight :size="18"/></button><button @click="emit('navigate', 'messages')"><span class="quick-icon"><MessageCircle :size="21"/></span><div><strong>回应访客</strong><p>查看留言，认真回复每个问题</p></div><ArrowUpRight :size="18"/></button></div>
      <div class="quiet-note"><Leaf :size="16"/><span>好的连接，从一份真诚的内容开始。今天，也给会客厅添一点新意吧。</span></div>
    </template>
  </section>
</template>
